    (void)bufsize;
    char numstr[128];
    if (decimals == 0)
        snprintf(numstr, sizeof(numstr), "%.0f", val);
    else
        snprintf(numstr, sizeof(numstr), "%.*f", decimals, val);

    int len = (int)strlen(numstr);
    int is_neg = (numstr[0] == '-');
    int start = is_neg ? 1 : 0;

    int int_len = 0;
    while (start + int_len < len && numstr[start + int_len] != '.') int_len++;

    int pos = 0;
    if (is_neg) buf[pos++] = '-';

    int first_group = int_len % 3;
    if (first_group == 0 && int_len > 0) first_group = 3;

    for (int i = 0; i < int_len; i++) {
        if (i > 0 && (i == first_group || (i - first_group) % 3 == 0))
            buf[pos++] = ',';
        buf[pos++] = numstr[start + i];
    }

    if (start + int_len < len) {
        int remaining = len - start - int_len;
        memcpy(buf + pos, numstr + start + int_len, remaining);
        pos += remaining;
    }
    buf[pos] = '\0';
}

