import heapq

def main():
    with open("__FIXTURE_DIR__/graph.json", "r") as f:
        data = json.load(f)

    nodes = data["nodes"]
    edges = data["edges"]

    # Build adjacency list (undirected)
    adj = {node: [] for node in nodes}
    for e in edges:
        u, v, w = e["from"], e["to"], e["weight"]
        adj[u].append((v, w))
        adj[v].append((u, w))

    # Dijkstra's algorithm from node "A"
    INF = float("inf")
    dist = {node: INF for node in nodes}
    dist["A"] = 0

    visited = set()
    pq = [(0, "A")]

    while pq:
        d, u = heapq.heappop(pq)
        if u in visited:
            continue
        visited.add(u)
        for v, w in adj[u]:
            if v not in visited:
                nd = d + w
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))

    # Output
    print("=== Shortest Paths from A ===")
    print()
    for node in sorted(nodes):
        d = dist[node]
        if d == INF:
            print(f"A -> {node}: infinity")
        elif isinstance(d, float) and d == int(d):
            print(f"A -> {node}: {int(d)}")
        else:
            print(f"A -> {node}: {d}")

main()

