function main(): void {
  const filePath = '__FIXTURE_DIR__/graph.json';
  const data: string = fs.readFileSync(filePath, 'utf-8');
  const graph: Graph = JSON.parse(data);

  // Build adjacency list (undirected)
  const adj = new Map<string, { node: string; weight: number }[]>();
  for (const node of graph.nodes) {
    adj.set(node, []);
  }
  for (const edge of graph.edges) {
    adj.get(edge.from)!.push({ node: edge.to, weight: edge.weight });
    adj.get(edge.to)!.push({ node: edge.from, weight: edge.weight });
  }

  // Dijkstra's algorithm from node "A"
  const dist = new Map<string, number>();
  const visited = new Set<string>();

  for (const node of graph.nodes) {
    dist.set(node, Infinity);
  }
  dist.set('A', 0);

  for (let i = 0; i < graph.nodes.length; i++) {
    // Select unvisited node with minimum distance
    let u: string | null = null;
    let minDist = Infinity;
    for (const node of graph.nodes) {
      if (!visited.has(node) && dist.get(node)! < minDist) {
        minDist = dist.get(node)!;
        u = node;
      }
    }

    if (u === null) break;

    visited.add(u);

    // Relax all edges from u
    const neighbors = adj.get(u)!;
    for (const { node: v, weight } of neighbors) {
      if (!visited.has(v)) {
        const newDist = dist.get(u)! + weight;
        if (newDist < dist.get(v)!) {
          dist.set(v, newDist);
        }
      }
    }
  }

  // Output
  const sortedNodes = [...graph.nodes].sort();
  const lines: string[] = [];
  lines.push('=== Shortest Paths from A ===');
  lines.push('');
  for (const node of sortedNodes) {
    const d = dist.get(node)!;
    lines.push(`A -> ${node}: ${d}`);
  }
  process.stdout.write(lines.join('\n') + '\n');
}

