    if (!*out) return NULL;
    int j = 0;
    for (int i = 0; i < len; i++) {
        if (s[i] == '\\' && s[i + 1]) {
            i++;
            switch (s[i]) {
                case 'n': (*out)[j++] = '\n'; break;
                case 't': (*out)[j++] = '\t'; break;
                case 'r': (*out)[j++] = '\r'; break;
                case '"': (*out)[j++] = '"'; break;
                case '\\': (*out)[j++] = '\\'; break;
                case '/': (*out)[j++] = '/'; break;
                case 'b': (*out)[j++] = '\b'; break;
                case 'f': (*out)[j++] = '\f'; break;
                default: (*out)[j++] = s[i]; break;
            }
        } else {
            (*out)[j++] = s[i];
        }
    }
    (*out)[j] = '\0';
    return s + len + 1;
}

