    let values = try? fileURL.resourceValues(forKeys: [.isSymbolicLinkKey, .isRegularFileKey])
    if let isSymlink = values?.isSymbolicLink, isSymlink {
        continue
    }
    guard let isRegular = values?.isRegularFile, isRegular else {
        continue
    }

    let fullPath = fileURL.path
    let relativePath = fullPath.replacingOccurrences(of: baseDir + "/", with: "")

    guard let data = try? Data(contentsOf: fileURL) else {
        continue
    }

    let charCount = data.count

    var lineCount = 0
    if !data.isEmpty {
        let newlineCount = data.reduce(0) { count, byte in
            byte == 10 ? count + 1 : count
        }
        if data.last == 10 {
            lineCount = newlineCount
        } else {
            lineCount = newlineCount + 1
        }
    }

    let ext = fileURL.pathExtension
    let extKey = ext.isEmpty ? "" : "." + ext

    let stats = FileStats(relativePath: relativePath, lines: lineCount, chars: charCount)

    if extensionGroups[extKey] == nil {
        extensionGroups[extKey] = []
    }
    extensionGroups[extKey]?.append(stats)

    totalFiles += 1
    totalLines += lineCount
    totalChars += charCount
}

