#define BASE_DIR "__FIXTURE_DIR__/project_tree"
#define PATH_BUF 16384

typedef struct {
    char *relpath;
    long lines;
    long chars;
    char *ext;
} FileEntry;

static FileEntry *files = NULL;
static size_t nfiles = 0, capfiles = 0;

static void add_file(const char *fullpath, const char *relpath) {
    if (nfiles >= capfiles) {
        capfiles = capfiles ? capfiles * 2 : 128;
        files = realloc(files, capfiles * sizeof(FileEntry));
        if (!files) exit(1);
    }
    FileEntry *e = &files[nfiles++];
    e->relpath = strdup(relpath);
    if (!e->relpath) exit(1);

    long lines = 0, chars = 0;
    FILE *f = fopen(fullpath, "rb");
    if (f) {
        int c;
        while ((c = fgetc(f)) != EOF) {
            chars++;
            if (c == '\n') lines++;
        }
        fclose(f);
    }
    e->lines = lines;
    e->chars = chars;

    const char *lastslash = strrchr(e->relpath, '/');
    const char *fname = lastslash ? lastslash + 1 : e->relpath;
    const char *dot = strrchr(fname, '.');
    if (dot) {
        e->ext = strdup(dot);
    } else {
        e->ext = strdup("(no extension)");
    }
    if (!e->ext) exit(1);
}

static void walk(const char *dir, const char *reldir) {
    DIR *d = opendir(dir);
    if (!d) return;
    struct dirent *ent;
    while ((ent = readdir(d)) != NULL) {
        if (ent->d_name[0] == '.' && ent->d_name[1] == '\0') continue;
        if (ent->d_name[0] == '.' && ent->d_name[1] == '.' && ent->d_name[2] == '\0') continue;

        char fullpath[PATH_BUF];
        char relpath[PATH_BUF];
        snprintf(fullpath, sizeof(fullpath), "%s/%s", dir, ent->d_name);
        if (reldir[0] == '\0')
            snprintf(relpath, sizeof(relpath), "%s", ent->d_name);
        else
            snprintf(relpath, sizeof(relpath), "%s/%s", reldir, ent->d_name);

